import{_ as e,o as a,c as r,ai as d}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Node(TS) · 语言与运行时总结","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/nodejs/language.md","filePath":"tech-system/backend/nodejs/language.md"}'),o={name:"tech-system/backend/nodejs/language.md"};function n(l,t,s,i,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="node-ts-·-语言与运行时总结" tabindex="-1">Node(TS) · 语言与运行时总结 <a class="header-anchor" href="#node-ts-·-语言与运行时总结" aria-label="Permalink to “Node(TS) · 语言与运行时总结”">​</a></h1><blockquote><p>这里的栈是 <strong>Node.js 运行时 + TypeScript 语言</strong>（不是纯前端 TS）。<br> 重点：<strong>同一套 TS 打通前端与桌面，服务端怎么用才不踩坑。</strong></p></blockquote><hr><h2 id="先分清两层" tabindex="-1">先分清两层 <a class="header-anchor" href="#先分清两层" aria-label="Permalink to “先分清两层”">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>是什么</th><th>我怎么选</th></tr></thead><tbody><tr><td><strong>语言</strong></td><td>TypeScript（底层仍是 JS）</td><td>后端默认 TS，不靠裸 JS 扛中型服务</td></tr><tr><td><strong>运行时</strong></td><td>Node.js</td><td>BFF / 实时 / Electron 本地服务</td></tr></tbody></table><hr><h2 id="node-运行时的核心特点" tabindex="-1">Node 运行时的核心特点 <a class="header-anchor" href="#node-运行时的核心特点" aria-label="Permalink to “Node 运行时的核心特点”">​</a></h2><ul><li><strong>事件循环 + 非阻塞 I/O</strong>：适合高连接、等待多的场景</li><li><strong>与前端同语言</strong>：BFF、工具链、Electron 配套成本低</li><li><strong>单线程执行 JS/TS</strong>：CPU 重活会堵住整进程</li></ul><p>一句话：Node 强在 <strong>等 I/O</strong>，弱在 <strong>算得凶</strong>。</p><hr><h2 id="typescript-我怎么看-在-node-上" tabindex="-1">TypeScript 我怎么看（在 Node 上） <a class="header-anchor" href="#typescript-我怎么看-在-node-上" aria-label="Permalink to “TypeScript 我怎么看（在 Node 上）”">​</a></h2><ul><li>类型是协作与重构的安全带，动态 JS 写大会痛</li><li>编译到 JS 再跑；类型只在开发期，不替代运行时校验</li><li>和前端共用类型/工具链时收益最大</li></ul><hr><h2 id="适合什么-不适合什么" tabindex="-1">适合什么 / 不适合什么 <a class="header-anchor" href="#适合什么-不适合什么" aria-label="Permalink to “适合什么 / 不适合什么”">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不适合</th></tr></thead><tbody><tr><td>BFF、聚合接口、WebSocket</td><td>重 CPU、复杂强事务核心域（优先 Java）</td></tr><tr><td>Electron 本地服务、前端同构</td><td>「为了用 Node 而用 Node」重写整套 ERP</td></tr><tr><td>实时通知、轻网关</td><td>无类型纪律的大团队长期协作</td></tr></tbody></table><hr><h2 id="我为什么用-node-ts" tabindex="-1">我为什么用 Node(TS) <a class="header-anchor" href="#我为什么用-node-ts" aria-label="Permalink to “我为什么用 Node(TS)”">​</a></h2><ol><li>前端 Vue、桌面 Electron 已在栈内，本地服务与 BFF 同语言最省事</li><li>和 Java 分工：Java 管域与库表，Node 管靠近端的聚合与实时</li><li>不为炫技上 Nest 全家桶；场景简单就 Express/Fastify + TS</li></ol><p>框架细节 → <a href="./frameworks.html">框架总结</a></p>',19)])])}const g=e(o,[["render",n]]);export{b as __pageData,g as default};
